Here is the class, using SQLite storage, synchronous writes for atomicity, and an hourly alarm that reschedules itself.

```typescript
import { DurableObject } from "cloudflare:workers";

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

const HOUR_MS = 60 * 60 * 1000;

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS meta (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
      `);
      // Only set an alarm if none is pending, so constructor reruns don't push it back.
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // No awaits between the statements, so each call is a single atomic write.
  // Requests to one room are handled one at a time by the input gate.
  async postMessage(author: string, body: string): Promise<number> {
    return this.ctx.storage.sql
      .exec<{ id: number }>(
        "INSERT INTO messages (author, body, created_at) VALUES (?, ?, ?) RETURNING id",
        author,
        body,
        Date.now(),
      )
      .one().id;
  }

  async getMessages(limit = 50): Promise<{ id: number; author: string; body: string; created_at: number }[]> {
    return this.ctx.storage.sql
      .exec<{ id: number; author: string; body: string; created_at: number }>(
        "SELECT id, author, body, created_at FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse();
  }

  async setState(key: string, value: string): Promise<void> {
    this.ctx.storage.sql.exec(
      "INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      key,
      value,
    );
  }

  async getState(key: string): Promise<string | null> {
    const rows = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM meta WHERE key = ?", key)
      .toArray();
    return rows[0]?.value ?? null;
  }

  // Hourly housekeeping: prune messages older than 24h, then schedule the next run.
  async alarm(): Promise<void> {
    this.ctx.storage.sql.exec(
      "DELETE FROM messages WHERE created_at < ?",
      Date.now() - 24 * HOUR_MS,
    );
    this.ctx.storage.sql.exec(
      "INSERT INTO meta (key, value) VALUES ('last_alarm', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      String(Date.now()),
    );
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}
```

Wire it up in `wrangler.jsonc`, and route by room name:

```jsonc
{
  "durable_objects": {
    "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }]
  },
  "migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
}
```

```typescript
const room = env.CHAT_ROOM.getByName(roomId);
await room.postMessage("ola", "hello");
```

Notes:
- The 24-hour pruning in `alarm()` is a placeholder for whatever hourly work you want. Replace it as needed.
- The alarm is armed in the constructor, so a room starts its hourly cycle on first use.
- If `alarm()` throws, Cloudflare retries it with backoff, and the reschedule happens only on success.
